using NaughtyAttributes;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "PurifyEffectAmountAction", menuName = "Data/Battle/Battle Actions/Purification Actions/PurifyEffectAmount Action")]
public class PurifyEffectAmountAction : PurifyCorruptWithMultiplierActions
{
	[Header("Effect")]
	[SerializeField]
	protected Effect effect;

	[SerializeField]
	private bool removeEffectAfterUse;

	[SerializeField]
	private bool gainEffect;

	[SerializeField]
	[ShowIf("gainEffect")]
	private BattleAction gainEffectAction;

	[SerializeField]
	[ShowIf("gainEffect")]
	private int gainEffectAmount;

	[SerializeField]
	private bool modifyEffectsBeforePurify;

	[SerializeField]
	private bool spendEffect;

	[SerializeField]
	[ShowIf("spendEffect")]
	private int spendEffectAmount;

	public Effect Effect => effect;

	public bool GainEffect => gainEffect;

	public BattleAction GainEffectAction => gainEffectAction;

	public int GainEffectAmount => gainEffectAmount;

	public bool SpendEffect => spendEffect;

	public int SpendEffectAmount => spendEffectAmount;

	public override int PurifyCounter(bool checkConditionToBeCastedOrPreview)
	{
		if (!base.isOnBattleScene)
		{
			return 0;
		}
		int num = 0;
		if (gainEffect && modifyEffectsBeforePurify && checkConditionToBeCastedOrPreview)
		{
			num = gainEffectAmount;
		}
		return ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<UnitEffects>().IsEffectActiveGetAmount(effect, activateFeedback: false) + num;
	}

	protected override void BeforePurify(GameObject source)
	{
		if (modifyEffectsBeforePurify)
		{
			ModifyEffects(source);
		}
	}

	protected override void AfterPurify(GameObject source)
	{
		if (!modifyEffectsBeforePurify)
		{
			ModifyEffects(source);
		}
	}

	private void ModifyEffects(GameObject source)
	{
		PlayerEffects component = ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<PlayerEffects>();
		if (removeEffectAfterUse)
		{
			component.RemoveEffect(effect);
		}
		if (gainEffect)
		{
			gainEffectAction.CastTargetAmount(ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject, gainEffectAmount, source);
		}
		if (spendEffect)
		{
			component.DecreaseEffect(effect, spendEffectAmount);
		}
	}
}
